import{_ as s,l as i,o as e,c as l,v as r,p as n,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"买卖价差成本","description":"","frontmatter":{"title":"买卖价差成本","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/spread-cost.md","filePath":"quant/spread-cost.md","lastUpdated":1789023840000}'),E={name:"quant/spread-cost.md"};function u(_,a,h,A,m,b){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="买卖价差成本" tabindex="-1">买卖价差成本 <a class="header-anchor" href="#买卖价差成本" aria-label="Permalink to &quot;买卖价差成本&quot;">​</a></h1><div class="epigraph"><p>有效成本可以从每日高低价与收盘价里估计出来，而不必拥有逐笔报价；把这个成本乘上换手，才是组合承担的价差账单。</p><footer>—— Hasbrouck, Trading Costs and Returns for U.S. Equities: Estimating Effective Costs from Daily Data, Journal of Finance, 2009</footer></div><p><a href="/quant/drawdown-calmar">上一课</a>用路径风险收束组合评价。缺口是实施：组合权重要先付买卖价差才能变成可交易。<a href="/quant/effective-realized-spread">有效价差与实现价差</a> 回答已经成交的一笔有多贵；<a href="/quant/spread-decomposition">价差分解</a> 回答宽出来的那一截补偿的是处理、存货还是逆向选择。组合构建还需要第三件事：在没有逐笔、甚至只有日频数据时，给每一只股票一个<strong>事前</strong>的半价差，用来惩罚换手、估算实施缺口。Hasbrouck（2009）用贝叶斯 Gibbs 在 Roll 型结构上从日数据恢复有效成本；Torre 的 BARRA 市场冲击手册则把报价价差写成冲击模型里与数量无关的一项，再叠加随规模上升的冲击。两者都是把「价差」变成优化器里的 \\(c_i\\)，而不是微观结构论文里的识别对象。本篇写这张成本怎么进组合，以及它和冲击项如何分工。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主动组合的预期换手会把每只股票的往返成本加总成组合层面的期望损耗。最瘦的会计是</p> \\[\\mathbb{E}[\\text{spread cost}]\\approx\\sum_i \\frac{s_i}{2}\\,|\\Delta w_i|\\,V, \\]<p>\\(s_i\\) 是相对价差，\\(V\\) 是组合净值，\\(|\\Delta w_i|\\) 是权重变动。没有 \\(s_i\\)，<a href="/quant/portfolio-constraints">换手约束</a> 只能用统一基点，小盘与大盘被同等惩罚，优化器会过度交易薄股票。问题是：\\(s_i\\) 从哪来，频率多高，以及它是否已经包含你还要另算的冲击。</p><p>报价价差 \\(A-B\\) 只对立刻吃一档的市价单近似成立，且许多历史样本没有可靠 BBO。有效价差含价格改善，通常小于报价价差。Hasbrouck 的日频有效成本针对的是可在 CRSP 一类数据库上复现的研究与回测；交易台用自己的执行短fall 校准。身份不同，\\(s_i\\) 不同，见 <a href="/quant/net-edge">净边缘</a> 对机构 / 零售管道的讨论。不存在一个对所有账户通用的「A 股价差表」。</p><h3 id="价差项与冲击项不要双计也不要漏计" tabindex="-1">价差项与冲击项不要双计也不要漏计 <a class="header-anchor" href="#价差项与冲击项不要双计也不要漏计" aria-label="Permalink to &quot;价差项与冲击项不要双计也不要漏计&quot;">​</a></h3><p>Torre 的市场冲击模型把交易成本拆成：与数量无关（或几乎无关）的价差成分，以及随 \\(Q/\\mathrm{ADV}\\) 上升的冲击成分。小单的主导项往往是半价差；大单的主导项是冲击，见 <a href="/quant/sqrt-impact">平方根冲击</a>。回测若已用主动侧报价成交（买在卖价），再减半价差，就是双计。若用中点成交且不减任何 \\(s_i\\)，就是漏计。方法必须与成交假设绑定：中点回测减有效半价差；主动侧回测只加超额改善 / 走阔与冲击。</p><p><span class="marginnote">Hasbrouck（2009）估计的是有效成本，不是报价宽度，也不是 Kyle 的 \\(\\lambda\\)。把它直接当作冲击函数的截距可以；再在同一笔交易上叠加完整的有效价差，会把同一层摩擦数两遍。成本模块应列一张「成交假设 × 成本项」对照表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>日频 Hasbrouck / Gibbs。</strong> 在 Roll 的成交价 = 有效价值 + 半价差 × 方向 的结构上，用高低价、收盘价等日频信息做贝叶斯估计，得到股票–年度（或更短窗）的有效成本 \\(c_{i,t}\\)。优点是覆盖面广、可复现、能接到长期因子回测。缺点是日频识别在信息交易强、方向序列相关时会偏，与 <a href="/quant/roll-model">Roll 模型</a> 的识别条件同源。应按市值、波动、换手分层检查 \\(c_{i,t}\\) 是否单调合理，并截断极端值以免优化器把某只股票当成「免费」。</p><p><strong>报价与有效价差面板。</strong> 有 tick 时，用成交量加权有效价差的滚动中位数当 \\(s_i\\)，比用最新一笔报价更稳。开盘、收盘拍卖应单独一套 \\(s_i\\)，或从日历再平衡的成本里剔除拍卖机制不可比的部分。Huang–Stoll 的实现价差更接近做市商事后收入，对主动方事前预算偏短；事前应用有效价差或短fall，事后用实现价差做执行质量评估。</p><p><strong>Torre / BARRA 式成本。</strong> 把预测成本写成 \\(c(Q)=s/2+\\eta\\sigma(Q/V)^{\\delta}\\)，小 \\(Q\\) 时第一项主导。组合优化里对 \\(|\\Delta w|\\) 用第一项，对大的 \\(|\\Delta w|\\) 切换或叠加第二项。参数按流动性分组校准，而不是全市场一个 \\(s\\)。换手惩罚 \\(c^\\top|\\Delta w|\\) 里的 \\(c\\) 应至少随股票变化；更细的做法是分段线性，避免平方根项把 QP 变成非凸——非凸时用局部线性化或把大单从优化里拿出去交给执行算法。</p><h3 id="把-接到换手与再平衡" tabindex="-1">把 \\(s_i\\) 接到换手与再平衡 <a class="header-anchor" href="#把-接到换手与再平衡" aria-label="Permalink to &quot;把 $s_i$ 接到换手与再平衡&quot;">​</a></h3><p>成本进入两处：优化器的线性惩罚，以及<a href="/quant/rebalance-rules">再平衡</a>的禁交易带宽度。\\(s_i\\) 上升时，带宽应加宽，否则规则会在价差最宽的日子最勤快地交易。日历再平衡若碰巧落在指数调整日，应使用当日的有效价差而不是月均 \\(s_i\\)。因子研究里按 Novy-Marx–Velikov 的精神，先按换手分档，再对每档用统一规则乘上该档的平均有效成本，避免只给低换手策略看净收益。</p><p><span class="marginnote">印花税、佣金、交易所规费与价差是不同科目。A 股卖出印花税是确定性比例，应进 \\(c_i\\) 的税费桶，不要混进 Hasbrouck 估计。融券费率是空头特有的流成本，按持有期累积，不是按 \\(|\\Delta w|\\) 一次性发生。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>价差成本的机制是即时流动性的标价：你要在时间 \\(t\\) 改变持仓，就必须与簿上已有的报价成交，或挂单等待并承担不执行风险。半价差是「立刻执行」的标价；挂单把这笔成本换成等待与逆向选择，期望成本可以更低，但不是零，也不能在回测里按中点成交还声称自己走了被动。Hasbrouck 日频估计把许多笔的有效成本压缩成一个慢变量，适合战略换手，不适合日内执行。</p><p>Torre 把价差写成冲击公式的截距，是承认：即使数量趋于一笔最小单位，往返仍要付一轮买卖。Kyle 的线性冲击过原点，不含这一截；把 Kyle \\(\\lambda\\) 当全部成本，会低估小单、高估或低估大单取决于校准。组合层的换手大多由大量中小单构成，截距项往往主导总账单——这是为什么「只建模冲击、不建模价差」的回测在降低频率后净收益改善得不像冲击模型预测的那么多：降频省下的是冲击，省不下每笔仍在付的半价差。</p><h3 id="截面差异如何扭曲因子" tabindex="-1">截面差异如何扭曲因子 <a class="header-anchor" href="#截面差异如何扭曲因子" aria-label="Permalink to &quot;截面差异如何扭曲因子&quot;">​</a></h3><p>\\(s_i\\) 与市值、波动、价格水平相关。等权小盘因子的毛溢价里有很大一块是在付价差；价值加权后价差账单下降，溢价也变。用统一 10bp 惩罚，会相对高估小盘因子的净 IR，低估大盘动量的净 IR。Hasbrouck 把有效成本与横截面收益联系起来，正是为了问：交易成本能否解释部分异常。本篇不需要完成那个资产定价命题；工程上只需保证 \\(c_i\\) 的截面排序与真实流动性排序一致，以免优化器的「低成本替代」选错。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Gibbs / Roll 型估计在涨跌停、一字板、长期停牌上失效，应标记缺失并用流动性分组的截面预测填补，而不是用 0。暗池与零售内化使有效价差小于可见报价，机构短fall 可能低于 Hasbrouck 日频估计；用偏高的 \\(c_i\\) 做研究偏保守，用它做交易台考核则不公。反过来，用自己一段平静期的短fall 去回测危机月份，会低估账单。</p><p>不要把报价价差除以二再乘双边换手，就称为「完整交易成本」——还缺冲击、借券、延误。不要在已经按卖价成交的回测上再减 Hasbrouck 成本。不要用全市场平均价差去惩罚一个只交易沪深 300 的增强产品。成本模型应随制度修订：最小报价单位变化、做市商制度、盘后交易，都会改 \\(s_i\\) 的水平，参数要分段。</p><p><span class="marginnote">\\(s_i\\) 应定期重估。用五年前的 Hasbrouck 截面去惩罚今日的换手，会在价差整体收窄的市场里过度约束，或在结构变差的小盘上约束不足。成本参数与风险模型一样有版本，要写进回测配置。</span></p>',27)),(e(),n(p,null,{default:t(()=>[d(o,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20TD%0A%20%20DATA%5B%22%E6%97%A5%E9%A2%91%E9%AB%98%E4%BD%8E%E6%94%B6%20%2F%20%E6%88%96%20tick%20%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20S%5B%22%E8%82%A1%E7%A5%A8%E6%9C%89%E6%95%88%E5%8D%8A%E4%BB%B7%E5%B7%AE%20s_i%2F2%22%5D%0A%20%20H%5B%22Hasbrouck%20Gibbs%22%5D%20--%3E%20S%0A%20%20T%5B%22Torre%20%E6%88%AA%E8%B7%9D%E9%A1%B9%22%5D%20--%3E%20S%0A%20%20S%20--%3E%20PEN%5B%22%E6%8D%A2%E6%89%8B%E6%83%A9%E7%BD%9A%20c%E2%8A%A4%7C%CE%94w%7C%22%5D%0A%20%20IMP%5B%22%E8%A7%84%E6%A8%A1%E4%BE%9D%E8%B5%96%E5%86%B2%E5%87%BB%22%5D%20--%3E%20TOT%5B%22%E6%80%BB%E5%AE%9E%E6%96%BD%E6%88%90%E6%9C%AC%22%5D%0A%20%20PEN%20--%3E%20TOT%0A%20%20TOT%20--%3E%20QP%5B%22%E4%BC%98%E5%8C%96%E4%B8%8E%E5%86%8D%E5%B9%B3%E8%A1%A1%E5%B8%A6%E5%AE%BD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>组合层的价差成本是 \\(\\sum (s_i/2)|\\Delta w_i|\\)，需要股票层面的事前 \\(s_i\\)，而不是微观结构分解本身。</li><li>Hasbrouck（2009）从日数据估计有效成本，便于长期回测；Torre / BARRA 把价差写成冲击模型的截距，与数量项分工。</li><li>成交假设必须与是否再减半价差一致，避免与主动侧成交或冲击项双计。</li><li>\\(s_i\\) 的截面差异会扭曲等权小盘一类因子的净 IR；统一基点惩罚不够。</li><li>税费、借券与价差分桶；A 股涨跌停样本上的日频估计应作缺失处理。</li><li>出处：Hasbrouck, <em>Trading Costs and Returns for U.S. Equities</em>, Journal of Finance, 2009；Torre, BARRA <em>Market Impact Model Handbook</em>；Roll, <em>Journal of Finance</em>, 1984；执行会计见 Huang and Stoll, <em>Journal of Financial Economics</em>, 1996。</li></ul>',2))])}const q=s(E,[["render",u]]);export{B as __pageData,q as default};
